// 作者、身份、新尾和真实回执严格同启；原死亡继位档不因存在原政策字符串自动启用本功能。
#include "political_head_handover_profile.hpp"
#include "resident/domains/politics/succession/political_succession_profile.hpp"
#include "resident/domains/organization/organization_office_history.hpp"
namespace hanmo::resident {
bool is_political_head_handover_fact_kind(const StableId& k){return k=="political_head_handover_offered"||k=="political_head_handover_accepted"||k=="political_head_handover_declined"||k=="political_head_handover_withdrawn";}
Outcome<Integer> political_head_handover_selected_version(const std::vector<std::pair<StableId,StableId>>& modules){Integer count=0,version=0;for(const auto& m:modules)if(m.first==political_head_handover_domain){if((m.second!="1"&&m.second!="2")||++count!=1)return {false,0,common_failure("PoliticalHeadHandoverModuleMismatch").error};version=m.second=="1"?1:2;}if(!count)return {true,0,{}};auto original=political_succession_selected_version(modules);if(!original.ok)return original;if(original.value!=1)return {false,0,common_failure("PoliticalHeadHandoverOriginalProfileRequired").error};return {true,version,{}};}
// 必须作者同时声明两份独立政策，不能由旧提名或原控制换人推导新生前交割条款。
Outcome<std::optional<PoliticalHeadHandoverCatalog>> decode_political_head_handover_profile(const BoundaryValue& scenario,const std::vector<StableId>& caps){const auto* dynamic=scenario.find("dynamic_world");const auto* group=dynamic?dynamic->find(political_head_handover_domain):nullptr;if(!group)return {true,std::nullopt,{}};if((std::find(caps.begin(),caps.end(),"political_head_handovers_v1")==caps.end()&&std::find(caps.begin(),caps.end(),"political_head_handovers_v2")==caps.end()))return {false,{},common_failure("PoliticalHeadHandoverCapabilityRequired").error};auto original=decode_political_succession_profile(scenario,caps);if(!original.ok)return {false,{},original.error};if(!original.value)return {false,{},common_failure("PoliticalHeadHandoverOriginalProfileRequired").error};auto decoded=decode_political_head_handover_catalog(*group);if(!decoded.ok)return {false,{},decoded.error};if(decoded.value.policies.empty()||decoded.value.policies.size()>4096)return {false,{},common_failure("InvalidPoliticalHeadHandoverCatalog").error};return {true,std::move(decoded.value),{}};}
Status validate_political_head_handover_layout(const CommonStore& common,const std::vector<std::pair<StableId,StableId>>& modules,const PoliticalHeadHandoverState* state){auto selected=political_head_handover_selected_version(modules);if(!selected.ok)return {false,{},selected.error};if(bool(state)!=(selected.value!=0)||(state&&state->version!=selected.value))return common_failure("PoliticalHeadHandoverProfileMismatch");if(!state){for(const auto& row:common.state().facts.rows())if(is_political_head_handover_fact_kind(row.second.kind)||row.second.domain==political_head_handover_domain)return common_failure("PoliticalHeadHandoverProfileRequired",row.first);for(const auto& h:common.state().history)if(is_political_head_handover_command(h.kind))return common_failure("PoliticalHeadHandoverProfileRequired",h.result_id);for(const auto& row:common.state().results.rows())if(row.second&&is_political_head_handover_command(row.second->kind))return common_failure("PoliticalHeadHandoverProfileRequired",row.first);}return common_success();}
// Common JSON只豁免恰一真实本账载荷，不用整个domain冒任意额外事实。
Status validate_political_head_handover_fact_header(const CommonStore& common,const PoliticalHeadHandoverState& s,const FactRecord& h){auto n=political_head_handover_fact_sequence(common,h.id);const auto* a=s.offers.find(h.id);const auto* b=s.answers.find(h.id);const auto* c=s.withdrawals.find(h.id);if((s.version!=1&&s.version!=2)||!n||h.domain!=political_head_handover_domain||Integer(bool(a))+Integer(bool(b))+Integer(bool(c))!=1)return common_failure("PoliticalHeadHandoverFactMismatch",h.id);const auto& id=a?a->id:b?b->id:c->id;const StableId kind=a?"political_head_handover_offered":b?(b->accepted?"political_head_handover_accepted":"political_head_handover_declined"):"political_head_handover_withdrawn";return id==h.id&&h.kind==kind?common_success():common_failure("PoliticalHeadHandoverFactMismatch",h.id);}
bool valid_political_head_handover_effect(const StableId& kind,const PoliticsEffects& e){if(!is_political_head_handover_command(kind)||!e.appointment_id.empty()||e.fact_ids.size()!=1)return false;const auto& source=e.fact_ids.front();if(kind==political_head_handover_offer_command)return organization_instance_sequence(source,"political_head_handover_offer").has_value()&&e.receipt_ids.empty();if(kind==political_head_handover_withdraw_command)return organization_instance_sequence(source,"political_head_handover_withdrawal").has_value()&&e.receipt_ids.empty();if(organization_instance_sequence(source,"political_head_handover_decline"))return e.receipt_ids.empty();return organization_instance_sequence(source,"political_head_handover_acceptance").has_value()&&e.receipt_ids.size()==1&&organization_instance_sequence(e.receipt_ids.front(),"organization").has_value();}
}
